using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class FlattenModelFolders {
static string R=>Path.GetFullPath(Path.Combine(Directory.GetParent(Application.dataPath).FullName,"../../tmp/ModelFolderCleanup_20261103"));
static void Folder(string path){if(AssetDatabase.IsValidFolder(path))return;string parent=Path.GetDirectoryName(path).Replace('\\','/');Folder(parent);string guid=AssetDatabase.CreateFolder(parent,Path.GetFileName(path));if(string.IsNullOrEmpty(guid))throw new Exception("Cannot create "+path);}
static string[] Dependencies(string path)=>AssetDatabase.GetDependencies(path,true).Select(AssetDatabase.AssetPathToGUID).Where(x=>!string.IsNullOrEmpty(x)).Distinct().OrderBy(x=>x).ToArray();
public static string Main(){if(EditorApplication.isPlaying)throw new Exception("Edit mode required");var plan=JArray.Parse(File.ReadAllText(R+"/move_plan.json"));var scenes=((JArray)JObject.Parse(File.ReadAllText(R+"/asset_inventory.json"))["scenes"]).Select(x=>(string)x).ToArray();var before=scenes.ToDictionary(s=>s,s=>Dependencies(s));var ids=new Dictionary<string,string[]>();foreach(var a in plan){string p=(string)a["path"];if(Path.GetExtension(p)==".fbx")ids[(string)a["guid"]]=AssetDatabase.LoadAllAssetsAtPath(p).Where(x=>x!=null).Select(x=>{AssetDatabase.TryGetGUIDAndLocalFileIdentifier(x,out string g,out long id);return id+":"+x.GetType().FullName;}).OrderBy(x=>x).ToArray();}
File.WriteAllText(R+"/scene_dependency_guids_before.json",JsonConvert.SerializeObject(before,Formatting.Indented));File.WriteAllText(R+"/model_subasset_ids_before.json",JsonConvert.SerializeObject(ids,Formatting.Indented));var completed=new List<JObject>();foreach(var a in plan.Where(x=>(bool)x["move"]))Folder(Path.GetDirectoryName((string)a["destination"]).Replace('\\','/'));
AssetDatabase.StartAssetEditing();try{foreach(JObject a in plan.Where(x=>(bool)x["move"])){string src=(string)a["path"],dst=(string)a["destination"],guid=(string)a["guid"];if(AssetDatabase.GUIDToAssetPath(guid)!=src)throw new Exception("Asset moved concurrently: "+src);string error=AssetDatabase.MoveAsset(src,dst);if(!string.IsNullOrEmpty(error))throw new Exception(error);completed.Add(a);if(completed.Count%20==0)File.WriteAllText(R+"/move_progress.json",JsonConvert.SerializeObject(new{moved=completed.Count,total=plan.Count(x=>(bool)x["move"])}));}}
catch{foreach(var a in completed.AsEnumerable().Reverse()){string old=(string)a["path"],now=(string)a["destination"];if(!File.Exists(old)&&AssetDatabase.GUIDToAssetPath((string)a["guid"])==now)AssetDatabase.MoveAsset(now,old);}throw;}finally{AssetDatabase.StopAssetEditing();}
AssetDatabase.SaveAssets();AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);var guidChecks=plan.Select(a=>new{source=(string)a["path"],destination=(string)a["destination"],guid=(string)a["guid"],preserved=AssetDatabase.GUIDToAssetPath((string)a["guid"])==(string)a["destination"]}).ToArray();if(guidChecks.Any(x=>!x.preserved))throw new Exception("GUID mismatch");var dependencyChecks=scenes.Select(s=>new{scene=s,guidDependenciesPreserved=before[s].SequenceEqual(Dependencies(s)),count=before[s].Length}).ToArray();if(dependencyChecks.Any(x=>!x.guidDependenciesPreserved))throw new Exception("Scene dependency GUIDs changed");var idChecks=ids.Select(pair=>new{guid=pair.Key,path=AssetDatabase.GUIDToAssetPath(pair.Key),subassetIdsPreserved=pair.Value.SequenceEqual(AssetDatabase.LoadAllAssetsAtPath(AssetDatabase.GUIDToAssetPath(pair.Key)).Where(x=>x!=null).Select(x=>{AssetDatabase.TryGetGUIDAndLocalFileIdentifier(x,out string g,out long id);return id+":"+x.GetType().FullName;}).OrderBy(x=>x))}).ToArray();if(idChecks.Any(x=>!x.subassetIdsPreserved))throw new Exception("Model subasset IDs changed");
var cleanRoots=new[]{"Assets/Afrer_Seconds/05.Model","Assets/Afrer_Seconds/03.Art/Candidates/VARCO"};var deleted=new List<string>();foreach(string root in cleanRoots){var dirs=AssetDatabase.GetAllAssetPaths().Where(p=>p.StartsWith(root+"/")&&AssetDatabase.IsValidFolder(p)).OrderByDescending(p=>p.Length).ToArray();foreach(var dir in dirs){bool keep=dir=="Assets/Afrer_Seconds/05.Model/Props"||dir=="Assets/Afrer_Seconds/05.Model/Player"||dir=="Assets/Afrer_Seconds/05.Model/Environment"||dir=="Assets/Afrer_Seconds/05.Model/Enemy"||dir.EndsWith("/Materials")||dir.EndsWith("/Textures")||System.Text.RegularExpressions.Regex.IsMatch(dir,@"05.Model/(Props|Environment)/(B[1-5]|1F|Common)$");if(!keep&&Directory.Exists(dir)&&!Directory.EnumerateFileSystemEntries(dir).Any()){if(!AssetDatabase.DeleteAsset(dir))throw new Exception("Cannot remove empty folder "+dir);deleted.Add(dir);}}}
var prefabChecks=plan.Where(a=>Path.GetExtension((string)a["destination"])==".prefab").Select(a=>{string path=(string)a["destination"];var p=AssetDatabase.LoadAssetAtPath<GameObject>(path);var ts=p.GetComponentsInChildren<Transform>(true);return new{path=path,missingScripts=ts.Sum(t=>GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject)),missingMeshes=p.GetComponentsInChildren<MeshFilter>(true).Count(m=>!m.sharedMesh),missingMaterials=p.GetComponentsInChildren<Renderer>(true).Sum(rr=>rr.sharedMaterials.Count(m=>!m))};}).ToArray();if(prefabChecks.Any(x=>x.missingScripts>0||x.missingMeshes>0||x.missingMaterials>0))throw new Exception("Missing prefab reference");
var result=new{assetsChecked=plan.Count,moved=completed.Count,guidChecks,dependencyChecks,idChecks,prefabChecks,removedEmptyFolders=deleted};File.WriteAllText(R+"/move_verification.json",JsonConvert.SerializeObject(result,Formatting.Indented));return JsonConvert.SerializeObject(new{moved=completed.Count,allGuidsPreserved=true,sceneDependenciesPreserved=dependencyChecks.Length,modelSubassetIdsPreserved=idChecks.Length,prefabsVerified=prefabChecks.Length,emptyFoldersRemoved=deleted.Count});}}
